#!/bin/sh
# claim-05: concrete-trace witness (kind concrete_trace_violation)
# Generated by evidence/mutants/gen_mutants.py; see mutation.json and STATUS.md.
# Semantics: KEVM in the pinned checker image sha256:7d4a35bc05dfdad97b244da3c75bb3c3e710be73713cac3ca1c5bb6226cdc465
# (kprove argv = pilot/checker/run-claim.sh's, inlined because this runs from a bundle copy).
# On the shared VM, hold a prover slot around the caller (do not lock in here).
set -u
IMG=sha256:7d4a35bc05dfdad97b244da3c75bb3c3e710be73713cac3ca1c5bb6226cdc465
T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT
kp() {  # kp <claim file in this dir> <module>: kprove stdout -> $T/<module>.out, stderr -> .err
  docker run --rm --platform linux/amd64 --network none --memory=6g --cpus=2 \
    --user "$(id -u):$(id -g)" -e HOME=/tmp -v "$PWD:/claim:ro" -w /tmp "$IMG" \
    kprove "/claim/$1" --definition /opt/kevm/haskell \
      -I /opt/kevm/evm-semantics-source -I /opt/kevm/plugin --spec-module "$2" \
    >"$T/$2.out" 2>"$T/$2.err"
}
python3 -I - "$@" <<'PY' || { echo "BINDING-CHECK-FAILED"; exit 3; }
import re, sys
def hexof(p): return open(p, "rb").read().hex()
def progs(p): return re.findall(r'#parseByteStack\("0x([0-9a-f]+)"\)', open(p, encoding="utf-8").read())
art, mut = hexof("../../../hard/artifact.bin"), hexof("mutant.bin")
assert art != mut, "mutant.bin equals the artefact"
assert progs("witness-original.k")[:2] == [art, art] and len(progs("witness-original.k")) == 4, "control claim not bound to hard/artifact.bin"
assert progs("witness-mutant.k")[:2] == [mut, mut] and len(progs("witness-mutant.k")) == 4, "witness claim not bound to mutant.bin"
assert progs("witness-negative.k")[:2] == [mut, mut] and len(progs("witness-negative.k")) == 4, "negative control not bound to mutant.bin"
PY

kp witness-original.k CLAIM05-CONCRETE-ORIGINAL; rc_o=$?
kp witness-mutant.k CLAIM05-CONCRETE-MUTANT; rc_m=$?
kp witness-negative.k CLAIM05-CONCRETE-NEGATIVE; rc_n=$?
acc() { [ "$1" -eq 0 ] && grep -q '#Top' "$T/$2.out"; }
echo "claim: claim-05 (join() reverts)"
echo "mutation: join() live check neutralised: EQ -> OR at 0x34e, so live == 1 becomes 1 | live (always non-zero) and the JUMPI past the revert is always taken"
echo "state: concrete, see mutation.json"
if acc $rc_o CLAIM05-CONCRETE-ORIGINAL; then echo "control: original artefact on this state reverts, as the claim says (kprove #Top)"; \
  else echo "control: NOT accepted (exit $rc_o)"; fi
if acc $rc_m CLAIM05-CONCRETE-MUTANT; then echo "witness: mutant on this state halts with EVMC_SUCCESS (kprove #Top)"; \
  else echo "witness: NOT accepted (exit $rc_m)"; fi
if acc $rc_n CLAIM05-CONCRETE-NEGATIVE; then echo "negative control: the claim at this state on the mutant WAS accepted (harness not discriminating)"; \
  else echo "negative control: the claim at this state on the mutant is not accepted"; fi
if acc $rc_o CLAIM05-CONCRETE-ORIGINAL && acc $rc_m CLAIM05-CONCRETE-MUTANT && ! acc $rc_n CLAIM05-CONCRETE-NEGATIVE; then
  echo "TCG-VIOLATION: claim-05 join() mutant halts with EVMC_SUCCESS where the claim requires EVMC_REVERT on the same concrete state"
  exit 0
fi
echo "NO-VIOLATION-SHOWN"
exit 1
